        LocalDate date = LocalDate.parse(dateStr);
        String csv = reportService.generateOccupancyReport(date);
        ctx.contentType("text/csv; charset=utf-8").result(csv);
    }

    private void getRevenueReport(Context ctx) {
        String monthStr = ctx.queryParam("month");
        if (monthStr == null) {
            throw new ReservationService.InvalidRequestException("Missing month parameter");
        }

        YearMonth month = YearMonth.parse(monthStr);
        String csv = reportService.generateRevenueReport(month);
        ctx.contentType("text/csv; charset=utf-8").result(csv);
    }

    private ReservationDto toDto(Reservation r) {
        return new ReservationDto(
            r.id(),
            r.roomNumber(),
            r.guestName(),
            r.guestEmail(),
            r.guestCpf(),
            r.checkIn(),
            r.checkOut(),
            r.guests(),
            r.ratePlan(),
            r.nights(),
            r.subtotal(),
            r.discount(),
            r.total(),
            r.status(),
            r.amountPaid(),
            r.refund()
        );
    }

    private DocumentDto buildReceipt(Reservation r) {
        return new DocumentDto(
            "Comprovante de reserva",
            r.id(),
            r.guestName(),
            r.guestCpf(),
            r.roomNumber(),
            r.roomType(),
            r.checkIn(),
            r.checkOut(),
            r.nights(),
            r.subtotal(),
            r.discount(),
            r.total()
        );
    }

    record RoomDto(int number, RoomType type, int capacity, BigDecimal nightlyRate) {}

    record CreateReservationDto(
        int roomNumber,
        String guestName,
        String guestEmail,
        String guestCpf,
        LocalDate checkIn,
        LocalDate checkOut,
        int guests,
        RatePlan ratePlan
    ) {}

    record ReservationDto(
        int id,
        int roomNumber,
        String guestName,
        String guestEmail,
        String guestCpf,
        LocalDate checkIn,
        LocalDate checkOut,
        int guests,
        RatePlan ratePlan,
        int nights,
        BigDecimal subtotal,
        BigDecimal discount,
        BigDecimal total,
        ReservationStatus status,
        BigDecimal amountPaid,
        BigDecimal refund
    ) {}

    record DocumentDto(
        String title,
        int reservationId,
        String guestName,
        String guestCpf,
        int roomNumber,
        RoomType roomType,
        LocalDate checkIn,
        LocalDate checkOut,
        int nights,
        BigDecimal subtotal,
        BigDecimal discount,
        BigDecimal total
    ) {}

    record MessageDto(
        int id,
        MessageChannel channel,
        String to,
        String subject,
        String body
    ) {}
}

